style.css:
/* ===== Global modern look ===== */
:root{
  --bg: #0b1220;
  --card: rgba(255,255,255,0.06);
  --text: rgba(255,255,255,0.9);
  --muted: rgba(255,255,255,0.65);
  --border: rgba(255,255,255,0.12);
  --accent: #6ee7ff;
  --shadow: 0 18px 50px rgba(0,0,0,0.45);
}

html, body{
  background: radial-gradient(circle at 20% 10%, rgba(110,231,255,0.18), transparent 50%),
              radial-gradient(circle at 90% 30%, rgba(167,139,250,0.18), transparent 50%),
              var(--bg) !important;
  color: var(--text) !important;
  font-family: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif !important;
}

/* Links */
a{
  color: var(--accent) !important;
  text-decoration: none !important;
}
a:hover{ text-decoration: underline !important; }

/* Make most sections look like glass cards */
div, section, main, article, header, nav, aside, footer{
  border-radius: 16px !important;
}

/* Cards + panels */
div, section, article, main{
  background: transparent;
}

/* Inputs / forms */
input, textarea, select, button{
  background: rgba(255,255,255,0.08) !important;
  border: 1px solid var(--border) !important;
  color: var(--text) !important;
  border-radius: 12px !important;
  padding: 10px 12px !important;
  outline: none !important;
  box-shadow: none !important;
}

button, input[type="submit"]{
  cursor: pointer;
  background: linear-gradient(135deg, rgba(110,231,255,0.25), rgba(167,139,250,0.20)) !important;
  border: 1px solid rgba(110,231,255,0.30) !important;
}
button:hover, input[type="submit"]:hover{
  transform: translateY(-1px);
  box-shadow: var(--shadow) !important;
}

/* Tables look clean */
table{
  width: 100% !important;
  border-collapse: separate !important;
  border-spacing: 0 !important;
  overflow: hidden !important;
  border-radius: 16px !important;
  border: 1px solid var(--border) !important;
  background: rgba(255,255,255,0.05) !important;
}
th, td{
  padding: 12px 14px !important;
  border-bottom: 1px solid rgba(255,255,255,0.08) !important;
}
th{
  color: var(--text) !important;
  background: rgba(255,255,255,0.06) !important;
}
tr:hover td{
  background: rgba(255,255,255,0.06) !important;
}

/* Scrollbar (Chrome/Edge) */
::-webkit-scrollbar{ width: 10px; }
::-webkit-scrollbar-track{ background: rgba(255,255,255,0.05); }
::-webkit-scrollbar-thumb{
  background: rgba(255,255,255,0.22);
  border-radius: 100px;
}

/* Kill ugly hard-coded bright backgrounds */
*[style*="background: white"], *[style*="background-color: white"]{
  background: transparent !important;
}
